import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { DatabaseSync } from 'node:sqlite';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createServer } from 'node:net';

test('moves remember per-project order persistently, preserve task data and summaries, and reject invalid ownership', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-moves-'));
  const databasePath = join(directory, 'workboard.sqlite');
  const legacy = new DatabaseSync(databasePath);
  legacy.exec(`
    CREATE TABLE projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL);
    CREATE TABLE tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL,
      title TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0, position INTEGER NOT NULL);
    INSERT INTO projects (name) VALUES ('Source'), ('Destination'), ('Archived');
    INSERT INTO tasks (project_id, title, completed, position) VALUES
      (1, 'Oldest', 1, 20), (2, 'Destination first', 0, 10), (1, 'Source remaining', 0, 30);
  `);
  legacy.close();
  const socket = createServer();
  socket.listen(0, '127.0.0.1');
  await once(socket, 'listening');
  const port = socket.address().port;
  await new Promise((resolve) => socket.close(resolve));
  const base = `http://127.0.0.1:${port}`;
  let child;
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: String(port), DB_PATH: databasePath },
      stdio: ['ignore', 'ignore', 'pipe'],
    });
    let errors = '';
    child.stderr.on('data', (data) => { errors += data; });
    for (let i = 0; i < 100; i++) {
      if (child.exitCode !== null) throw new Error(errors);
      try {
        if ((await fetch(`${base}/health`)).ok) return;
      } catch { /* Wait until the server listens. */ }
      await new Promise((resolve) => setTimeout(resolve, 25));
    }
    throw new Error(`Server did not start: ${errors}`);
  }
  async function stop() {
    if (!child || child.exitCode !== null) return;
    const exited = once(child, 'exit');
    child.kill('SIGTERM');
    await exited;
  }
  const request = (path, method, body) => fetch(`${base}/api/projects${path}`, {
    method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
  });
  const tasks = async (project) => (await request(`/${project}/tasks`, 'GET')).json();
  const move = (source, task, destination) => request(`/${source}/tasks/${task}/move`, 'POST', {
    destination_project_id: destination,
  });
  try {
    await start();
    assert.deepEqual((await tasks(1)).map((task) => task.id), [1, 3]);
    await request('/1/tasks/1', 'PATCH', { priority: 'High' });
    await request('/1/tasks/1', 'PATCH', { due_date: '2024-02-29' });
    await request('/2', 'PATCH', { default_task_priority: 'Low' });
    await request('/2', 'PATCH', { name: 'Renamed destination' });
    await request('/3', 'PATCH', { archived: true });
    const [original, remaining] = await tasks(1);
    for (const value of [1, 0, -1, null, '2', 1.5]) {
      assert.equal((await move(1, 1, value)).status, 400);
    }
    assert.equal((await move(1, 1, 999)).status, 404);
    assert.equal((await move(1, 1, 3)).status, 409);
    assert.equal((await move(2, 1, 1)).status, 404);
    assert.equal((await move(1, 999, 2)).status, 404);
    assert.deepEqual((await tasks(1))[0], original);
    const moved = await move(1, 1, 2);
    assert.equal(moved.status, 200);
    assert.deepEqual(await moved.json(), original);
    assert.deepEqual((await tasks(1)).map((task) => task.id), [3]);
    assert.deepEqual((await tasks(2)).map((task) => task.id), [2, 1]);
    const projects = await (await request('', 'GET')).json();
    assert.deepEqual(projects.map(({ completed, total }) => [completed, total]), [[0, 1], [1, 2], [0, 0]]);
    const created = await (await request('/2/tasks', 'POST', { title: 'After move' })).json();
    assert.equal(created.priority, 'Low');
    assert.deepEqual((await tasks(2)).map((task) => task.id), [2, 1, created.id]);
    await stop();
    await start();
    assert.deepEqual((await tasks(2))[1], original);
    assert.deepEqual((await tasks(2)).map((task) => task.id), [2, 1, created.id]);
    await request('/2', 'PATCH', { archived: true });
    assert.equal((await move(2, 1, 1)).status, 409);
    await request('/2', 'PATCH', { archived: false });
    assert.equal((await move(2, 1, 1)).status, 200);
    assert.deepEqual(await tasks(1), [original, remaining]);
    assert.deepEqual((await tasks(1)).map((task) => task.id), [1, 3]);
    // Blank dates and open completion state also survive a subsequent move.
    const blank = (await tasks(2))[0];
    assert.equal((await move(2, blank.id, 1)).status, 200);
    assert.deepEqual((await tasks(1))[2], blank);
    await stop();
    await start();
    assert.deepEqual((await tasks(1)).map((task) => task.id), [1, 3, 2]);
    assert.deepEqual((await tasks(1))[0], original);
    assert.deepEqual((await tasks(1))[2], blank);

    // Vacated positions stay reserved, even when all tasks leave a project.
    for (const id of [1, 3, 2]) assert.equal((await move(1, id, 2)).status, 200);
    assert.deepEqual(await tasks(1), []);
    assert.deepEqual((await tasks(2)).map((task) => task.id), [2, 1, created.id, 3]);
    const newSourceTask = await (await request('/1/tasks', 'POST', { title: 'Created while away' })).json();
    const firstArrival = await (await request('/2/tasks', 'POST', { title: 'First visit' })).json();
    assert.equal((await move(2, firstArrival.id, 1)).status, 200);
    await request('/2/tasks/1', 'PATCH', { title: 'Current title' });
    await request('/2/tasks/1', 'PATCH', { completed: false });
    await request('/2/tasks/1', 'PATCH', { priority: 'Low' });
    await request('/2/tasks/1', 'PATCH', { due_date: '9999-12-31' });
    const current = (await tasks(2)).find((task) => task.id === 1);
    await request('/1', 'PATCH', { name: 'Renamed source' });
    await request('/1', 'PATCH', { archived: true });
    assert.equal((await move(2, 1, 1)).status, 409);
    await stop();
    await start();
    await request('/1', 'PATCH', { archived: false });
    // Return in reverse order across a restart; original relative order wins.
    assert.equal((await move(2, 2, 1)).status, 200);
    assert.equal((await move(2, 3, 1)).status, 200);
    await stop();
    await start();
    assert.equal((await move(2, 1, 1)).status, 200);
    assert.deepEqual((await tasks(1)).map((task) => task.id), [1, 3, 2, newSourceTask.id, firstArrival.id]);
    assert.deepEqual((await tasks(1))[0], current);
    assert.deepEqual((await tasks(2)).map((task) => task.id), [created.id]);
    const summaries = await (await request('', 'GET')).json();
    assert.deepEqual(summaries.map(({ completed, total }) => [completed, total]), [[0, 5], [0, 1], [0, 0]]);
    // A second return restores the destination's independent remembered slots.
    for (const id of [3, 1, 2]) assert.equal((await move(1, id, 2)).status, 200);
    await stop();
    await start();
    assert.deepEqual((await tasks(2)).map((task) => task.id), [2, 1, created.id, 3]);
    assert.deepEqual((await tasks(2))[1], current);
  } finally {
    await stop();
    await rm(directory, { recursive: true, force: true });
  }
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { DatabaseSync } from 'node:sqlite';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createServer } from 'node:net';

test('moves remember per-project order persistently, preserve task data and summaries, and reject invalid ownership', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-moves-'));
  const databasePath = join(directory, 'workboard.sqlite');
  const legacy = new DatabaseSync(databasePath);
  legacy.exec(`
    CREATE TABLE projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL);
    CREATE TABLE tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL,
      title TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0, position INTEGER NOT NULL);
    INSERT INTO projects (name) VALUES ('Source'), ('Destination'), ('Archived');
    INSERT INTO tasks (project_id, title, completed, position) VALUES
      (1, 'Oldest', 1, 20), (2, 'Destination first', 0, 10), (1, 'Source remaining', 0, 30);
  `);
  legacy.close();
  const socket = createServer();
  socket.listen(0, '127.0.0.1');
  await once(socket, 'listening');
  const port = socket.address().port;
  await new Promise((resolve) => socket.close(resolve));
  const base = `http://127.0.0.1:${port}`;
  let child;
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: String(port), DB_PATH: databasePath },
      stdio: ['ignore', 'ignore', 'pipe'],
    });
    let errors = '';
    child.stderr.on('data', (data) => { errors += data; });
    for (let i = 0; i < 100; i++) {
      if (child.exitCode !== null) throw new Error(errors);
      try {
        if ((await fetch(`${base}/health`)).ok) return;
      } catch { /* Wait until the server listens. */ }
      await new Promise((resolve) => setTimeout(resolve, 25));
    }
    throw new Error(`Server did not start: ${errors}`);
  }
  async function stop() {
    if (!child || child.exitCode !== null) return;
    const exited = once(child, 'exit');
    child.kill('SIGTERM');
    await exited;
  }
  const request = (path, method, body) => fetch(`${base}/api/projects${path}`, {
    method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
  });
  const tasks = async (project) => (await request(`/${project}/tasks`, 'GET')).json();
  const move = (source, task, destination) => request(`/${source}/tasks/${task}/move`, 'POST', {
    destination_project_id: destination,
  });
  try {
    await start();
    assert.deepEqual((await tasks(1)).map((task) => task.id), [1, 3]);
    await request('/1/tasks/1', 'PATCH', { priority: 'High' });
    await request('/1/tasks/1', 'PATCH', { due_date: '2024-02-29' });
    await request('/2', 'PATCH', { default_task_priority: 'Low' });
    await request('/2', 'PATCH', { name: 'Renamed destination' });
    await request('/3', 'PATCH', { archived: true });
    const [original, remaining] = await tasks(1);
    for (const value of [1, 0, -1, null, '2', 1.5]) {
      assert.equal((await move(1, 1, value)).status, 400);
    }
    assert.equal((await move(1, 1, 999)).status, 404);
    assert.equal((await move(1, 1, 3)).status, 409);
    assert.equal((await move(2, 1, 1)).status, 404);
    assert.equal((await move(1, 999, 2)).status, 404);
    assert.deepEqual((await tasks(1))[0], original);
    const moved = await move(1, 1, 2);
    assert.equal(moved.status, 200);
    assert.deepEqual(await moved.json(), original);
    assert.deepEqual((await tasks(1)).map((task) => task.id), [3]);
    assert.deepEqual((await tasks(2)).map((task) => task.id), [2, 1]);
    const projects = await (await request('', 'GET')).json();
    assert.deepEqual(projects.map(({ completed, total }) => [completed, total]), [[0, 1], [1, 2], [0, 0]]);
    const created = await (await request('/2/tasks', 'POST', { title: 'After move' })).json();
    assert.equal(created.priority, 'Low');
    assert.deepEqual((await tasks(2)).map((task) => task.id), [2, 1, created.id]);
    await stop();
    await start();
    assert.deepEqual((await tasks(2))[1], original);
    assert.deepEqual((await tasks(2)).map((task) => task.id), [2, 1, created.id]);
    await request('/2', 'PATCH', { archived: true });
    assert.equal((await move(2, 1, 1)).status, 409);
    await request('/2', 'PATCH', { archived: false });
    assert.equal((await move(2, 1, 1)).status, 200);
    assert.deepEqual(await tasks(1), [original, remaining]);
    assert.deepEqual((await tasks(1)).map((task) => task.id), [1, 3]);
    // Blank dates and open completion state also survive a subsequent move.
    const blank = (await tasks(2))[0];
    assert.equal((await move(2, blank.id, 1)).status, 200);
    assert.deepEqual((await tasks(1))[2], blank);
    await stop();
    await start();
    assert.deepEqual((await tasks(1)).map((task) => task.id), [1, 3, 2]);
    assert.deepEqual((await tasks(1))[0], original);
    assert.deepEqual((await tasks(1))[2], blank);

    // Vacated positions stay reserved, even when all tasks leave a project.
    for (const id of [1, 3, 2]) assert.equal((await move(1, id, 2)).status, 200);
    assert.deepEqual(await tasks(1), []);
    assert.deepEqual((await tasks(2)).map((task) => task.id), [2, 1, created.id, 3]);
    const newSourceTask = await (await request('/1/tasks', 'POST', { title: 'Created while away' })).json();
    const firstArrival = await (await request('/2/tasks', 'POST', { title: 'First visit' })).json();
    assert.equal((await move(2, firstArrival.id, 1)).status, 200);
    await request('/2/tasks/1', 'PATCH', { title: 'Current title' });
    await request('/2/tasks/1', 'PATCH', { completed: false });
    await request('/2/tasks/1', 'PATCH', { priority: 'Low' });
    await request('/2/tasks/1', 'PATCH', { due_date: '9999-12-31' });
    const current = (await tasks(2)).find((task) => task.id === 1);
    await request('/1', 'PATCH', { name: 'Renamed source' });
    await request('/1', 'PATCH', { archived: true });
    assert.equal((await move(2, 1, 1)).status, 409);
    await stop();
    await start();
    await request('/1', 'PATCH', { archived: false });
    // Return in reverse order across a restart; original relative order wins.
    assert.equal((await move(2, 2, 1)).status, 200);
    assert.equal((await move(2, 3, 1)).status, 200);
    await stop();
    await start();
    assert.equal((await move(2, 1, 1)).status, 200);
    assert.deepEqual((await tasks(1)).map((task) => task.id), [1, 3, 2, newSourceTask.id, firstArrival.id]);
    assert.deepEqual((await tasks(1))[0], current);
    assert.deepEqual((await tasks(2)).map((task) => task.id), [created.id]);
    const summaries = await (await request('', 'GET')).json();
    assert.deepEqual(summaries.map(({ completed, total }) => [completed, total]), [[0, 5], [0, 1], [0, 0]]);
    // A second return restores the destination's independent remembered slots.
    for (const id of [3, 1, 2]) assert.equal((await move(1, id, 2)).status, 200);
    await stop();
    await start();
    assert.deepEqual((await tasks(2)).map((task) => task.id), [2, 1, created.id, 3]);
    assert.deepEqual((await tasks(2))[1], current);
  } finally {
    await stop();
    await rm(directory, { recursive: true, force: true });
  }
});

import { matchesTaskFilters, normalizeDueRange } from './task-filters.js';

const app = document.querySelector('#app');

async function api(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Unable to complete request');
  return data;
}

function showError(message) {
  const alert = app.querySelector('[role="alert"]');
  alert.textContent = message;
  alert.hidden = false;
}

function projectRow(project, onArchiveChange) {
  const row = document.createElement('li');
  row.dataset.testid = 'project-row';
  const name = document.createElement('span');
  name.textContent = project.name;
  const button = document.createElement('button');
  button.textContent = 'Open project';
  button.addEventListener('click', () => location.assign(`/projects/${project.id}`));
  const summary = document.createElement('span');
  summary.dataset.testid = 'project-summary';
  summary.textContent = `${project.completed}/${project.total} completed`;
  const archive = document.createElement('button');
  archive.textContent = project.archived ? 'Restore project' : 'Archive project';
  archive.addEventListener('click', async () => {
    archive.disabled = true;
    try {
      const saved = await api(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      Object.assign(project, saved);
      app.querySelector('[role="alert"]').hidden = true;
      onArchiveChange();
    } catch (error) {
      showError(error.message);
    } finally {
      archive.disabled = false;
    }
  });
  row.append(name, summary, button, archive);
  return row;
}

async function showProjects() {
  app.innerHTML = `
    <h1>Workboard</h1>
    <form>
      <label for="project-name">Project name</label>
      <div class="create-controls">
        <input id="project-name" name="name" type="text" autocomplete="off">
        <button type="submit">Create project</button>
      </div>
    </form>
    <p role="alert" hidden></p>
    <label for="project-filter">Project filter</label>
    <select id="project-filter">
      <option>Active</option>
      <option>Archived</option>
    </select>
    <ul class="projects"></ul>
  `;
  const list = app.querySelector('ul');
  const form = app.querySelector('form');
  const input = app.querySelector('input');
  const submit = form.querySelector('button');
  const filter = app.querySelector('select');
  let projects = [];
  function renderProjects() {
    const archived = filter.value === 'Archived';
    list.replaceChildren(...projects.filter((project) => Boolean(project.archived) === archived)
      .map((project) => projectRow(project, renderProjects)));
  }
  filter.addEventListener('change', renderProjects);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const name = input.value.trim();
    if (!name) return showError('Project name is required');
    submit.disabled = true;
    try {
      const project = await api('/api/projects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      projects.push(project);
      renderProjects();
      input.value = '';
      app.querySelector('[role="alert"]').hidden = true;
      input.focus();
    } catch (error) {
      showError(error.message);
    } finally {
      submit.disabled = false;
    }
  });
  // Load existing rows before allowing new submissions, preserving creation order.
  submit.disabled = true;
  try {
    projects = await api('/api/projects');
    renderProjects();
  } finally {
    submit.disabled = false;
  }
}

async function showProject(id) {
  app.innerHTML = '<button type="button">Projects</button><h1></h1><p role="alert" hidden></p>';
  app.querySelector('button').addEventListener('click', () => location.assign('/'));
  const project = await api(`/api/projects/${id}`);
  const destinations = (await api('/api/projects'))
    .filter((candidate) => !candidate.archived && candidate.id !== project.id);
  app.querySelector('h1').textContent = project.name;
  document.title = `${project.name} — Workboard`;
  const renameForm = document.createElement('form');
  renameForm.innerHTML = `
    <label for="new-project-name">New project name</label>
    <div class="create-controls">
      <input id="new-project-name" name="name" type="text" autocomplete="off">
      <button type="submit">Rename project</button>
    </div>
  `;
  const renameInput = renameForm.querySelector('input');
  const renameButton = renameForm.querySelector('button');
  renameInput.disabled = Boolean(project.archived);
  renameButton.disabled = Boolean(project.archived);
  renameForm.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (project.archived) return;
    const name = renameInput.value.trim();
    if (!name) return showError('Project name is required');
    renameButton.disabled = true;
    try {
      const saved = await api(`/api/projects/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      Object.assign(project, saved);
      app.querySelector('h1').textContent = project.name;
      document.title = `${project.name} — Workboard`;
      renameInput.value = '';
      app.querySelector('[role="alert"]').hidden = true;
    } catch (error) {
      showError(error.message);
    } finally {
      renameButton.disabled = Boolean(project.archived);
    }
  });
  app.append(renameForm);
  const section = document.createElement('section');
  section.innerHTML = `
    <label for="default-task-priority">Default task priority</label>
    <select id="default-task-priority">
      <option>Low</option>
      <option>Normal</option>
      <option>High</option>
    </select>
    <form>
      <label for="task-title">Task title</label>
      <div class="create-controls">
        <input id="task-title" name="title" type="text" autocomplete="off">
        <button type="submit" disabled>Create task</button>
      </div>
    </form>
    <label for="task-filter">Task filter</label>
    <select id="task-filter">
      <option>All</option>
      <option>Open</option>
      <option>Completed</option>
    </select>
    <label for="priority-filter">Priority filter</label>
    <select id="priority-filter">
      <option>All</option>
      <option>Low</option>
      <option>Normal</option>
      <option>High</option>
    </select>
    <form id="due-range-form">
      <label for="due-from">Due from</label>
      <input id="due-from" type="text" autocomplete="off">
      <label for="due-through">Due through</label>
      <input id="due-through" type="text" autocomplete="off">
      <button type="submit">Apply due range</button>
    </form>
    <ul class="tasks"></ul>
  `;
  if (project.archived) {
    const notice = document.createElement('p');
    notice.textContent = 'Archived project';
    app.append(notice);
  }
  app.append(section);
  const form = section.querySelector('form');
  const input = section.querySelector('input');
  const submit = form.querySelector('button');
  const filter = section.querySelector('#task-filter');
  const priorityFilter = section.querySelector('#priority-filter');
  const defaultPriority = section.querySelector('#default-task-priority');
  defaultPriority.value = project.default_task_priority;
  defaultPriority.disabled = true;
  defaultPriority.addEventListener('change', async () => {
    if (project.archived) return;
    defaultPriority.disabled = true;
    // Keep task creation behind the pending default write so it inherits the displayed value.
    submit.disabled = true;
    try {
      const saved = await api(`/api/projects/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ default_task_priority: defaultPriority.value }),
      });
      Object.assign(project, saved);
      app.querySelector('[role="alert"]').hidden = true;
    } catch (error) {
      showError(error.message);
    } finally {
      defaultPriority.value = project.default_task_priority;
      defaultPriority.disabled = Boolean(project.archived);
      submit.disabled = Boolean(project.archived);
    }
  });
  const list = section.querySelector('ul');
  const endpoint = `/api/projects/${id}/tasks`;
  let tasks = [];
  const pendingUpdates = new Set();
  let dueRange = normalizeDueRange('', '');
  const dueRangeForm = section.querySelector('#due-range-form');
  const dueFrom = section.querySelector('#due-from');
  const dueThrough = section.querySelector('#due-through');
  dueRangeForm.addEventListener('submit', (event) => {
    event.preventDefault();
    try {
      // Validate before replacing the applied range; draft input never changes membership.
      dueRange = normalizeDueRange(dueFrom.value, dueThrough.value);
      dueFrom.value = dueRange.from;
      dueThrough.value = dueRange.through;
      app.querySelector('[role="alert"]').hidden = true;
      renderTasks();
    } catch (error) {
      showError(error.message);
    }
  });

  function renderTasks() {
    const visible = tasks.filter((task) => matchesTaskFilters(task, filter.value, priorityFilter.value, dueRange));
    list.replaceChildren(...visible.map((task) => {
      const row = document.createElement('li');
      row.dataset.testid = 'task-row';
      const title = document.createElement('span');
      title.textContent = task.title;
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.completed;
      checkbox.disabled = Boolean(project.archived) || pendingUpdates.has(task.id);
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      const renameForm = document.createElement('form');
      const renameLabel = document.createElement('label');
      renameLabel.htmlFor = `new-task-title-${task.id}`;
      renameLabel.textContent = 'New task title';
      const renameInput = document.createElement('input');
      renameInput.id = renameLabel.htmlFor;
      renameInput.type = 'text';
      renameInput.autocomplete = 'off';
      const renameButton = document.createElement('button');
      renameButton.type = 'submit';
      renameButton.textContent = 'Rename task';
      renameInput.disabled = checkbox.disabled;
      renameButton.disabled = checkbox.disabled;
      renameForm.append(renameLabel, renameInput, renameButton);
      const priorityLabel = document.createElement('label');
      priorityLabel.htmlFor = `task-priority-${task.id}`;
      priorityLabel.textContent = 'Task priority';
      const priority = document.createElement('select');
      priority.id = priorityLabel.htmlFor;
      for (const value of ['Low', 'Normal', 'High']) {
        const option = document.createElement('option');
        option.value = option.textContent = value;
        priority.append(option);
      }
      priority.value = task.priority;
      priority.disabled = checkbox.disabled;
      const dueDateForm = document.createElement('form');
      const dueDateLabel = document.createElement('label');
      dueDateLabel.htmlFor = `task-due-date-${task.id}`;
      dueDateLabel.textContent = 'Task due date';
      const dueDateInput = document.createElement('input');
      dueDateInput.id = dueDateLabel.htmlFor;
      dueDateInput.type = 'text';
      dueDateInput.value = task.due_date;
      dueDateInput.autocomplete = 'off';
      dueDateInput.disabled = checkbox.disabled;
      const dueDateButton = document.createElement('button');
      dueDateButton.type = 'submit';
      dueDateButton.textContent = 'Save due date';
      dueDateButton.disabled = checkbox.disabled;
      dueDateForm.append(dueDateLabel, dueDateInput, dueDateButton);

      const moveForm = document.createElement('form');
      const destinationLabel = document.createElement('label');
      destinationLabel.htmlFor = `destination-project-${task.id}`;
      destinationLabel.textContent = 'Destination project';
      const destination = document.createElement('select');
      destination.id = destinationLabel.htmlFor;
      for (const project of destinations) {
        const option = document.createElement('option');
        option.value = project.id;
        option.textContent = project.name;
        destination.append(option);
      }
      const moveButton = document.createElement('button');
      moveButton.type = 'submit';
      moveButton.textContent = 'Move task';
      destination.disabled = moveButton.disabled = checkbox.disabled || destinations.length === 0;
      moveForm.append(destinationLabel, destination, moveButton);

      async function saveTask(update, moving = false) {
        if (project.archived || pendingUpdates.has(task.id)) return;
        pendingUpdates.add(task.id);
        checkbox.disabled = renameInput.disabled = renameButton.disabled = priority.disabled =
          dueDateInput.disabled = dueDateButton.disabled = destination.disabled = moveButton.disabled = true;
        try {
          const saved = await api(`${endpoint}/${task.id}${moving ? '/move' : ''}`, {
            method: moving ? 'POST' : 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(update),
          });
          if (moving) tasks = tasks.filter((candidate) => candidate.id !== task.id);
          else Object.assign(task, saved);
          app.querySelector('[role="alert"]').hidden = true;
        } catch (error) {
          showError(error.message);
        } finally {
          pendingUpdates.delete(task.id);
          renderTasks();
        }
      }
      checkbox.addEventListener('change', () => saveTask({ completed: checkbox.checked }));
      renameForm.addEventListener('submit', (event) => {
        event.preventDefault();
        if (project.archived || pendingUpdates.has(task.id)) return;
        const title = renameInput.value.trim();
        if (!title) return showError('Task title is required');
        saveTask({ title });
      });
      priority.addEventListener('change', () => saveTask({ priority: priority.value }));
      dueDateForm.addEventListener('submit', (event) => {
        event.preventDefault();
        saveTask({ due_date: dueDateInput.value });
      });
      moveForm.addEventListener('submit', (event) => {
        event.preventDefault();
        if (destinations.length === 0) return;
        saveTask({ destination_project_id: Number(destination.value) }, true);
      });
      row.append(title, checkbox, renameForm, priorityLabel, priority, dueDateForm, moveForm);
      return row;
    }));
  }

  filter.addEventListener('change', renderTasks);
  priorityFilter.addEventListener('change', renderTasks);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (project.archived) return;
    const title = input.value.trim();
    if (!title) return showError('Task title is required');
    submit.disabled = true;
    defaultPriority.disabled = true;
    try {
      const task = await api(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title }),
      });
      tasks.push(task);
      renderTasks();
      input.value = '';
      app.querySelector('[role="alert"]').hidden = true;
      input.focus();
    } catch (error) {
      showError(error.message);
    } finally {
      submit.disabled = Boolean(project.archived);
      defaultPriority.disabled = Boolean(project.archived);
    }
  });
  tasks = await api(endpoint);
  renderTasks();
  submit.disabled = Boolean(project.archived);
  defaultPriority.disabled = Boolean(project.archived);
}

try {
  const match = location.pathname.match(/^\/projects\/(\d+)$/);
  if (match) await showProject(match[1]);
  else await showProjects();
} catch (error) {
  showError(error.message);
} finally {
  app.setAttribute('aria-busy', 'false');
}

